import sys
from itertools import product

data = sys.stdin.read().split()
n = int(data[0])
E = [(int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n - 1)]
P = [2, 3, 5, 7, 11, 13]

def isp(x):
    return x > 1 and all(x % d for d in range(2, int(x ** 0.5) + 1))

pairs = [(i, j) for i in range(n - 1) for j in range(i + 1, n - 1) if set(E[i]) & set(E[j])]
for lab in product(P, repeat=n - 1):
    if all(isp(lab[i] + lab[j]) for i, j in pairs):
        print(' '.join(map(str, lab)))
        break
else:
    print(-1)

